import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.CreatePhoto{EntityUniqueID: 0x1122334455667788, PhotoName: "photo.png", ItemName: "Snapshot"}
PHOTO = bytes.fromhex("88776655443322110970686f746f2e706e6708536e617073686f74")

# generated by gophertunnel b8bd735:
# &packet.CreatePhoto{EntityUniqueID: -1}
NEGATIVE_ID = bytes.fromhex("ffffffffffffffff0000")

# generated by gophertunnel b8bd735:
# &packet.CreatePhoto{PhotoName: strings.Repeat("a", 200), ItemName: "x"}
LONG_NAME = bytes.fromhex(
    "0000000000000000c8016161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161"
    "6161616161616161616161616161616161616161616161616161616161610178"
)

GOLDENS = [
    pytest.param(
        v2225.CreatePhotoPacket(id=0x1122334455667788, photo_name="photo.png", photo_item_name="Snapshot"),
        PHOTO,
        id="photo",
    ),
    pytest.param(v2225.CreatePhotoPacket(id=-1), NEGATIVE_ID, id="negative-id"),
    pytest.param(
        v2225.CreatePhotoPacket(photo_name="a" * 200, photo_item_name="x"), LONG_NAME, id="200-character-name"
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_create_photo_is_packet_171(version):
    assert version.packets[171] is version.CreatePhotoPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_create_photo_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_create_photo_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
